// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (material.answersFile ?? (reviewedKey ? 'reviewed-' + grade : grade + '-answers') + '.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2013, "4-5", [{"author":"И. Иткин и С. Переверзева","question":"В каком слове нет уменьшительного суффикса?","choices":["<em>ананасик</em>","<em>арбузик</em>","<em>финик</em>","<em>огурчик</em>","<em>репка</em>."],"key":"В","review":["Уменьшительные названия","Найди обычные формы слов «ананасик», «арбузик», «огурчик» и «репка». Это «ананас», «арбуз», «огурец» и «репа».","В слове «финик» конечное «-ик» входит в корень. Сам плод называется фиником, а уменьшительно его можно назвать «финичек»."]},{"author":"А. Пиперски и А. Сомин","question":"Русский и чешский — близкородственные языки. Для чего используется устройство, которое по-чешски называется <em>pračka</em> (<em>č</em> читается как <em>ч</em>)?","choices":["для стирки","для освещения","для обогрева","для бритья","для приготовления пищи."],"key":"А","review":["Устройство по-чешски","Буква č читается как ч. Произнеси «прачка» и вспомни, что когда-то делала работница, которую так называли по-русски.","Прачка стирала бельё. Чешское pračka — стиральная машина, значит, устройство нужно для стирки."]},{"author":"Е. Кац","question":"Какое слово относится не к той части речи, что все остальные?","choices":["<em>ливень</em>","<em>метель</em>","<em>буран</em>","<em>позёмка</em>","<em>моросит</em>."],"key":"Д","review":["Слова о погоде","К словам «ливень», «метель», «буран» и «позёмка» можно задать вопрос «что?». Все они существительные.","«Моросит» сообщает, что делает дождь. Оно отвечает на вопрос «что делает?» и является глаголом."]},{"author":"А. Сомин","question":"Знаки препинания в арабской письменности выглядят практически так же, как и в русской. Какой знак препинания называется по-арабски словом <em>хиляль</em>, которое также значит ‘полумесяц’?","choices":["точка","восклицательный знак","вопросительный знак","скобка","тире."],"key":"Г","review":["Знак и полумесяц","Представь тонкий изогнутый полумесяц. Среди знаков ищи похожий изгиб.","Одна круглая скобка «(» или «)» имеет ту же форму дуги. У других знаков нет такого изгиба по всей длине."]},{"author":"И. Иткин и М. Тюренкова","question":"Какое дерево получило своё название из-за клейкого сока?","choices":["дуб","осина","ясень","липа","ольха."],"key":"Г","review":["Клейкий сок дерева","Из слова «клейкий» подбери близкое по смыслу слово «липкий». О соке можно сказать, что он прилипает к пальцам.","Слова «липа» и «липнуть» связаны по происхождению. Из названий деревьев «липа» подходит к признаку липкого сока."]},{"author":"К. Гилярова","question":"<em>У Малыша снова неприятности. Из-за Карлсона он всё время попадает в …</em>","choices":["<em>поделки</em>","<em>проделки</em>","<em>переделки</em>","<em>подделки</em>","<em>безделки</em>."],"key":"В","review":["Малыш и Карлсон","Подставь слова после «попадает в …». Нужное слово должно означать неприятную историю, в которой оказался Малыш.","«Переделка» — трудное или опасное положение. Карлсон устраивает проделки, а Малыш из-за них попадает в переделки."]},{"author":"Е. Бикмаев","question":"Дети писали сочинение на тему «Как я провёл лето». Миша написал: «Я был во ________». Какую страну скорее всего посетил Миша?","choices":["Грецию","Египет","Францию","Латвию","Венгрию<em>.</em>"],"key":"В","review":["Сочинение о лете","Спроси «где я был?» и измени названия стран. Получится «в Греции», «в Египте», «в Латвии» и «в Венгрии».","Перед «Франции» короткий предлог «в» создал бы трудный стык согласных, потому что слово начинается на фр. Обычно говорят «был во Франции», значит, он посетил Францию."]},{"author":"Б. Иомдин","question":"В каком примере слово <em>гусеница</em> означает не то, что в других?","choices":["<em>С дерева падали ягоды и гусеницы</em> (Б. Пастернак).","<em>Углубившись в ближайший лес, разведчики заметили свежие</em> <em>следы гусениц</em> (Э. Казакевич).","<em>Вот и решила она однажды напустить на его сад жуков и гусениц</em> (В. Лунин).","<em>Меня с детства больше интересовали лягушки, червяки, гусеницы, я</em> <em>часами изучала жизнь муравейника</em> (Е. Маркова).","<em>Он притаскивает в класс разных гусениц, а потом ещё и спрашивает</em> <em>у людей: «Ну, разве это не прелесть?..»</em> (А. Драбкина)."],"key":"Б","review":["Гусеницы в пяти отрывках","На деревьях, в саду и в рассказах о мелких животных «гусеницы» — личинки насекомых. Посмотри, кто мог оставить заметные следы в лесу.","Разведчики обнаружили следы гусеничной машины, например танка. «Гусеница» здесь означает ленту, которая движется вокруг колёс."]},{"author":"К. Гилярова","question":"Из какого слова <strong>нельзя</strong> получить другое слово, добавив букву <strong><em>у</em></strong> в начале?","choices":["<em>шип</em>","<em>дар</em>","<em>гол</em>","<em>дача</em>","из всех этих слов можно получить другое слово."],"key":"А","review":["Новое слово с у","Добавь «у» к «дар», «гол» и «дача». Получатся «удар», «угол» и «удача».","Из «шип» получается «ушип». Такого слова в обычном русском языке нет, поэтому «шип» — исключение."]},{"author":"И. Иткин","question":"Какое из этих слов никогда не употребляется в единственном числе?","choices":["<em>брёвна</em>","<em>поленья</em>","<em>дрова</em>","<em>щепки</em>","все эти слова достаточно часто употребляются в единственном числе."],"key":"В","review":["Слова про древесину","Назови один предмет из каждой группы, где это возможно. Одно бревно, одно полено, одна щепка — обычные формы.","«Дрова» употребляют только во множественном числе. Один кусок дров можно назвать поленом."]},{"author":"И. Иткин","question":"Сколько в русском языке названий месяцев, заканчивающихся на твёрдый согласный звук?","choices":["ни одного","одно","два","три","четыре."],"key":"В","review":["Последние звуки месяцев","Просмотри названия месяцев. Слово «май» оканчивается на мягкий [й’]. В названиях на ь, таких как «январь» и «июнь», последний согласный тоже мягкий.","«Март» заканчивается на твёрдый [т]. В «август» последним тоже слышится твёрдый [т]. Таких месяцев два."]},{"author":"А. Сомин","question":"В каком из этих слов есть приставка <em>не-</em>?","choices":["<em>немецкий</em>","<em>нежный</em>","<em>нервный</em>","<em>несчастный</em>","<em>небесный</em>."],"key":"Г","review":["Где есть приставка «не-»","Убери начальное «не-» и проверь, остаётся ли слово с подходящим смыслом. «Несчастный» можно объяснить как «лишённый счастья», а «счастный» сохранился, например, в выражении «счастный случай».","В словах «немецкий», «нежный», «нервный», «небесный» начальные «не» входят в корни. Приставка «не-» есть в «несчастный»."]},{"author":"В. Лунёв","question":"Тому, кто пытается скрыть очевидное, говорят, что ________ <em>в мешке не</em> <em>утаишь.</em> Какое слово мы пропустили?","choices":["<em>воды</em>","<em>денег</em>","<em>кота</em>","<em>шила</em>","<em>мыла</em>."],"key":"Г","review":["Что не утаишь","Вспомни предмет, который трудно спрятать в мешке, потому что он острый и может проткнуть ткань.","Шило — острый инструмент для прокалывания. Поэтому про явное говорят «шила в мешке не утаишь»."]},{"author":"Н. Валеева","question":"От слова <em>кусок</em> можно образовать уменьшительное <em>кусочек</em> с помощью суффикса <em>-ек</em>. От какого из данных ниже слов уменьшительное образуется с помощью того же суффикса?","choices":["<em>стол</em>","<em>стакан</em>","<em>карандаш</em>","<em>перец</em>","<em>горох</em>."],"key":"Д","review":["Уменьшительный суффикс","Поставь «кусочек» в форму «нет кусочка». В суффиксе «-ек» гласная исчезает. В суффиксе «-ик», как в «столик — столика», она остаётся.","Из «горох» получается «горошек — горошка», где тоже исчезает е. У «стаканчик», «карандашик» и «перчик» гласная остаётся."]},{"author":"Е. Бикмаев","question":"Названия чисел могут состоять из одних и тех же слов, расположенных в разном порядке. Например, <em>три</em> <em>тысячи</em> <em>четыре</em> (3004) и <em>четыре</em> <em>тысячи</em> <em>три</em> (4003). Название какого из четырёх данных чисел состоит не из того же набора слов, что остальные?","choices":["55000","50005","50050","5050","названия всех этих чисел состоят из одного и того же набора слов."],"key":"В","review":["Названия больших чисел","Прочитай 55 000, 50 005 и 5 050. В разных порядках в них звучат «пять», «пятьдесят» и «тысяч».","Число 50 050 читается «пятьдесят тысяч пятьдесят». Слово «пятьдесят» повторилось дважды, отдельного «пять» нет."]},{"author":"Е. Бикмаев","question":"В каком из предложений слово <em>переписать</em> означает не то, что в остальных?","choices":["<em>Мне понравилось это стихотворение, хочу</em> <strong><em>переписать</em></strong> <em>его в</em> <em>тетрадь.</em>","<em>В начале учебного года мне нужно было сходить в школу —</em> <strong><em>переписать</em></strong> <em>расписание.</em>","<em>Я написал контрольную работу на двойку — надо бы <strong>переписать</strong>.</em>","<em>Сегодня многим привычнее сфотографировать объявление, чем</em> <strong><em>переписать</em></strong> <em>его.</em>","<em>Легче составить план параграфа, чем</em> <strong><em>переписать</em></strong> <em>его целиком.</em>"],"key":"В","review":["Переписать текст","В тетрадь можно переписать уже готовое стихотворение, со стены — расписание или объявление, из учебника — параграф. В этих случаях копируют готовый текст.","Контрольную, написанную на двойку, хотят сделать заново. Здесь «переписать» значит снова выполнить работу."]},{"author":"И. Иткин и С. Переверзева","question":"На какую букву не могут заканчиваться слова?","choices":["<em>ж</em>","<em>ч</em>","<em>ш</em>","<em>щ</em>","<em>слова могут заканчиваться на любую из этих четырёх букв.</em>"],"key":"Д","review":["Буквы в конце","Попробуй подобрать слово на каждую букву. На ж оканчивается «нож», на ч — «мяч».","На ш оканчивается «душ», на щ — «плащ». Для каждой из четырёх букв нашёлся пример."]},{"author":"Е. Бикмаев","question":"Учитель написал на доске слова: … <em>пилы, … льва, … стены, … чеснока</em> — и попросил учеников вставить перед ними слова с корнем -<em>зуб</em>-. Какие слова нужно вставить ученикам?","choices":["<em>зубцы, зубы, зубья, зубчики</em>","<em>зубья, зубы, зубцы, зубчики</em>","<em>зубчики, зубья, зубцы, зубики</em>","<em>зубья, зубы, зубчики, зубцы</em>","<em>зубцы, зубы, зубчики, зубья</em>."],"key":"Б","review":["Похожие на зубы","Для льва выбери настоящие «зубы», для пилы — острые выступы «зубья». Осталось назвать верхушки стены и части головки чеснока.","У крепостной стены есть зубцы, у чеснока — зубчики. Порядок слов: зубья, зубы, зубцы, зубчики."]},{"author":"Е. Бикмаев и И. Иткин","question":"От четырёх из этих имён отчества образуются одним и тем же способом, а от одного <em>—</em> несколько иначе. От какого?","choices":["<em>Борис</em>","<em>Виктор</em>","<em>Олег</em>","<em>Роман</em>","<em>Яков</em>."],"key":"Д","review":["Пять отчеств","Произнеси «Борисович», «Викторович», «Олегович» и «Романович». Ко всем четырём именам присоединилось «-ович».","От Якова получаются «Яковлевич» и «Яковлевна». Перед «-евич» или «-евна» добавляется л, поэтому Яков стоит отдельно."]},{"author":"Л. Фёдорова","question":"Во Франции живут французы, в Англии — англичане, в Чехии — чехи. Название какой страны не связано с обычным названием её жителей?","choices":["Германии","Швеции","Греции","Швейцарии","Финляндии."],"key":"А","review":["Страны и народы","Сравни названия стран и жителей. Швеция — шведы, Греция — греки, Швейцария — швейцарцы, Финляндия — финны.","Жителей Германии обычно зовут немцами. В словах «Германия» и «немцы» разные корни."]},{"author":"Б. Иомдин","question":"В одной журнальной статье упоминается несколько городов мира. Какой город там <strong>не</strong> упоминается?","choices":["Ателета (Италия)","Гленелг (Шотландия)","Каанаак (Гренландия)","Оруро (Боливия)","Атланта (США)."],"key":"Д","review":["Названия городов","Прочитай «Ателета» и «Гленелг» с конца. Получатся те же слова. «Каанаак» и «Оруро» читаются так же в обе стороны.","У «Атланта» с конца получается «атналта». Это единственное название, которое не читается одинаково с обеих сторон."]},{"author":"А. Пиперски","question":"Какая из этих гласных букв никогда не встречается в окончаниях?","choices":["<em>ы</em>","<em>э</em>","<em>ю</em>","<em>я</em>","все эти буквы встречаются в окончаниях."],"key":"Б","review":["Гласная в окончании","Проверь окончания у изменяемых слов. В «столы» есть «-ы», в «говорю» — «-ю», в «земля» — «-я».","Слова вроде «алоэ» могут заканчиваться на э, но они не изменяются, а эта буква входит в основу. Окончания с э среди вариантов не бывает."]},{"author":"Л. Фёдорова","question":"Шведский писатель Сирус Гранер написал «Сказку о четырёх больших троллях и маленьком Вилле-пастухе». А как <strong>не</strong> могли звать этого маленького пастуха?","choices":["<em>Вилле</em>","<em>Вилль</em>","<em>Вилл</em>","<em>Вилла</em>","<em>Вилли</em>."],"key":"Д","review":["Имя маленького пастуха","В названии стоит форма «о Вилле». Имена Вилл, Вилль и Вилла дают такую форму после «о». Если исходное имя Вилле, оно не изменяется.","Вилли — неизменяемое имя на и. От него получилось бы «о Вилли-пастухе», поэтому оно не подходит."]},{"author":"И. Рубанов","question":"В этом маленьком кроссворде всего два слова, и четыре буквы из пяти в него уже вписаны. А какие к нему подойдут вопросы?","choices":["1. Правый ...\n2. ... святого","1. Тенистый ...\n2. Репчатый ...","1. Бодливый ...\n2. ... для ногтей","1. … для воды\n2. ... на чердак","Ни одна из этих пар вопросов не подходит."],"key":"Б","review":["Кроссворд из двух слов","В сетке по горизонтали «Б_К», по вертикали «Л_К». В обеих записях недостаёт одной и той же средней буквы.","«Тенистый бук» и «репчатый лук» подходят по смыслу. Впиши У в общую клетку и проверь оба слова."],"figure":{"condition":{"src":"assets/medvezhonok/2013/4-5-24.svg","width":218,"height":140,"alt":"Кроссворд. Слово 1 по горизонтали: Б, пустая клетка, К. Слово 2 по вертикали: Л, та же пустая клетка, К."}}},{"author":"Е. Муравенко и Л. Фёдорова","question":"Хорватский и русский языки родственны. По-хорватски ― Pepeljuga (Пепелюга), а по-русски...","choices":["Красная Шапочка","Золушка","Синеглазка","Курочка Ряба","Дюймовочка."],"key":"Б","review":["Сказка по-хорватски","В слове «Пепелюга» слышно «пепел». Какого сказочного героя можно вспомнить по связи с пеплом?","Золушка сидела у очага в золе. Зола и пепел остаются после горения, поэтому хорватское название подходит к Золушке."]},{"author":"А. Сомин","question":"В одном стихотворении С. Я. Маршака говорится, что Харитон «картинки хорошо умеет кистью рисовать», Эрик «чинит выключатель», а про Диму рассказывается, что «ходит он в больницу». А что из этого стихотворения можно узнать про Ульяну?","choices":["«строит дом»","«жнёт она пшеницу»","«чистит башмаки»","«учит деток в школе»","«самолётом режет облака»."],"key":"Г","review":["Кем работают герои","Определи занятия по описаниям. Харитон — художник, Эрик — электрик, Дима — доктор. Начало имени совпадает с началом профессии.","Для Ульяны ищи профессию на У. Это учительница, поэтому она «учит деток в школе»."]},{"author":"И. Иткин и С. Переверзева","question":"<em>Заглянуть за угол, накрыть на стол, подлезть под изгородь, отречься от</em> <em>престола...</em> Каким сочетанием можно продолжить этот ряд?","choices":["<em>заглянуть в комнату</em>","<em>перепрыгнуть через стену</em>","<em>свернуть с дороги</em>","<em>прийти по расписанию</em>","<em>купить к Новому году</em>."],"key":"В","review":["Начало глагола и предлог","Выдели приставки и предлоги. В примерах они совпадают: «за-глянуть за», «на-крыть на», «под-лезть под», «от-речься от».","Среди вариантов такая же пара — «с-вернуть с дороги». У остальных приставка и предлог записываются по-разному."]},{"author":"Б. Иомдин","question":"Шестая строчка одного шуточного текста выглядит так:\n<em>ольше нет укы Е</em>.\nА как выглядит его шестнадцатая строчка?","choices":["<em>ольше нет укы О</em>","<em>ольше нет укы П</em>","<em>ольш нт укы П</em>","<em>оьш т уы О</em>","<em>ьш т уы О</em>."],"key":"Г","review":["Буквы исчезают","Шестая буква алфавита — Е, шестнадцатая — О. Они стоят в конце своих строк. Каждая строка начинается остатком фразы «Больше нет буквы». В нём уже вычеркнуты все буквы, которые стоят в алфавите раньше названной.","К шестой строке из фразы ушли Б и В. К шестнадцатой из оставшегося «ольше нет укы» исчезают ещё Л, Е, Н и К. О вычеркнут только в следующей строке. Получается «оьш т уы О»."]},{"author":"М. Руссо","question":"В Костромской губернии его называли <em>тропинник</em>, в Вятской ― <em>путник</em>. О чём идет речь?","choices":["о лекарственном растении","о жалящем насекомом","о фольклорном жанре","о хлебобулочном изделии","о прохладительном напитке."],"key":"А","review":["Тропинник и путник","«Тропинник» связан с тропинкой, «путник» — с путём. Ищи знакомое название того, что встречается рядом с дорогой.","Подорожник часто растёт вдоль троп и дорог. Это лекарственное растение, поэтому «тропинник» и «путник» подходят ему по смыслу."]},{"author":"Ю. Вишневец и А. Сомин","question":"Даны два китайских слова и их переводы на русский язык: 火车 ‘паровоз’, 火山 ‘вулкан’. Переведите на русский язык ещё три слова: 车, 火 и 山.","choices":["гора, огонь, повозка","гора, повозка, огонь","повозка, гора, огонь","повозка, огонь, гора","огонь, повозка, гора."],"key":"Г","review":["Знаки для китайских слов","Сравни паровоз и вулкан. Общий знак 火 связан с огнём: в паровозе топят печь, а вулкан может извергать раскалённую лаву.","Знак 车 остаётся в названии транспорта и означает «повозка». 山 остаётся в названии вулкана и означает «гора». Порядок «повозка, огонь, гора»."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
